import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.userData.handlers = {};
  group.userData.dataBindings = config.dataBindings || [];

  let hoverTimeline = null;

  // Load mesh from GLB
  const gltf = ctx.glbLoader.load(config.meshUrl);
  const mesh = gltf.scene.children[0] || gltf.scene;

  if (mesh) {
    group.add(mesh);
  }

  // Apply scene transforms
  const pos = config.scenePosition || { x: 0, y: 0, z: 0 };
  group.position.set(pos.x, pos.y, pos.z);

  const rot = config.rotation || { x: 0, y: 0, z: 0 };
  group.rotation.order = 'XYZ';
  group.rotation.set(rot.x, rot.y, rot.z);

  const scl = config.scale || { x: 1, y: 1, z: 1 };
  group.scale.set(scl.x, scl.y, scl.z);

  // Apply cinematic primitives
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](group, primitive.params || {});
      }
    });
  }

  // Store original position for hover reset
  const originalY = group.position.y;

  // Hover handler: rise-in animation (0.15 scene units, power3.out, 0.7s)
  group.userData.handlers.onHover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, {
      y: originalY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    }, 0);
  };

  group.userData.handlers.onHoverEnd = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, {
      y: originalY,
      duration: 0.7,
      ease: 'power3.out',
    }, 0);
  };

  // Click handler: emit hub-collection.select event
  group.userData.handlers.onClick = () => {
    if (typeof config.onEvent === 'function') {
      config.onEvent('hub-collection.select');
    }
  };

  // Cleanup function
  group.userData.cleanup = () => {
    // Kill hover animation timeline
    if (hoverTimeline) hoverTimeline.kill();

    // Dispose geometry and materials
    group.traverse((node) => {
      if (node.isMesh) {
        if (node.geometry) node.geometry.dispose();
        if (Array.isArray(node.material)) {
          node.material.forEach((m) => m?.dispose?.());
        } else if (node.material) {
          node.material.dispose();
        }
      }
    });
  };

  return group;
}
